// main.zig — swscale candidate: pixel-format conversion and scaling that tracks
// FFmpeg's scalar libswscale (8.x) arithmetic, with @Vector fast paths.
//
// The pipeline mirrors swscale: per source line an input converter produces
// 15-bit intermediates, a horizontal FIR scales them, then per output line a
// vertical FIR plus an output writer packs the destination format.  Same-size
// conversions that FFmpeg serves with dedicated "unscaled" converters are
// reproduced separately (yuv2rgb tables, rgb2rgb shuffles, plane copies).

const std = @import("std");
const simd = @import("simd.zig");

const alloc = std.heap.c_allocator;

// ── Formats ─────────────────────────────────────────────────────────────────

const YUV420P = 0;
const YUV422P = 1;
const YUV444P = 2;
const NV12 = 3;
const NV21 = 4;
const RGB24 = 5;
const BGR24 = 6;
const RGBA = 7;
const BGRA = 8;
const GRAY8 = 9;

const ALGO_NEAREST = 0;
const ALGO_BILINEAR = 1;
const ALGO_BICUBIC = 2;

fn isRGB(f: c_int) bool {
    return f >= RGB24 and f <= BGRA;
}
fn isPlanarYUV(f: c_int) bool {
    return f <= NV21;
}
fn isSemi(f: c_int) bool {
    return f == NV12 or f == NV21;
}
fn hasAlphaFmt(f: c_int) bool {
    return f == RGBA or f == BGRA;
}
fn hSub(f: c_int) u5 {
    return switch (f) {
        YUV420P, YUV422P, NV12, NV21 => 1,
        else => 0,
    };
}
fn vSub(f: c_int) u5 {
    return switch (f) {
        YUV420P, NV12, NV21 => 1,
        else => 0,
    };
}
fn bpp(f: c_int) usize {
    return switch (f) {
        RGB24, BGR24 => 3,
        RGBA, BGRA => 4,
        else => 1,
    };
}
// byte offsets of R,G,B(,A) within a packed pixel
fn rIdx(f: c_int) usize {
    return switch (f) {
        RGB24, RGBA => 0,
        else => 2,
    };
}
fn bIdx(f: c_int) usize {
    return 2 - rIdx(f);
}

// ── Colour constants (BT.601 limited range, FFmpeg defaults) ────────────────

const RGB2YUV_SHIFT = 15;
fn coef(comptime x: f64, comptime scale: f64) i32 {
    return @intFromFloat(x * scale / 255.0 * @as(f64, 1 << RGB2YUV_SHIFT) + 0.5);
}
const RY: i32 = coef(0.299, 219);
const GY: i32 = coef(0.587, 219);
const BY: i32 = coef(0.114, 219);
const RU: i32 = -coef(0.169, 224);
const GU: i32 = -coef(0.331, 224);
const BU: i32 = coef(0.500, 224);
const RV: i32 = coef(0.500, 224);
const GV: i32 = -coef(0.419, 224);
const BV: i32 = -coef(0.081, 224);

// yuv2rgb coefficients (ff_yuv2rgb_coeffs[SWS_CS_DEFAULT], limited range)
const Yuv2Rgb = struct {
    ytab: [2048]u8,
    // table offsets indexed by clipped chroma (0..255)
    roff: [256]i32,
    guoff: [256]i32,
    gvoff: [256]i32,
    boff: [256]i32,
    // full-chroma writer coefficients
    y_off: i32,
    y_coeff: i32,
    v2r: i32,
    v2g: i32,
    u2g: i32,
    u2b: i32,
    // arithmetic form of ytab: ytab[i] = clip((yb0 + i*cy + 0x8000) >> 16)
    cy: i32,
    yb0: i64,

    fn roundToInt16(f: i64) i32 {
        const r: i64 = (f + (1 << 15)) >> 16;
        if (r < -0x7FFF) return -0x8000;
        if (r > 0x7FFF) return 0x7FFF;
        return @intCast(r);
    }

    fn init(t: *Yuv2Rgb) void {
        var crv: i64 = 104597;
        var cbu: i64 = 132201;
        var cgu: i64 = -25675;
        var cgv: i64 = -53279;
        var cy: i64 = 1 << 16;
        cy = @divTrunc(cy * 255, 219);
        const oy: i64 = 16 << 16;
        t.y_coeff = roundToInt16(cy * (1 << 13));
        t.y_off = roundToInt16(oy * (1 << 9));
        t.v2r = roundToInt16(crv * (1 << 13));
        t.v2g = roundToInt16(cgv * (1 << 13));
        t.u2g = roundToInt16(cgu * (1 << 13));
        t.u2b = roundToInt16(cbu * (1 << 13));
        crv = @divTrunc(crv * (1 << 16) + 0x8000, cy);
        cbu = @divTrunc(cbu * (1 << 16) + 0x8000, cy);
        cgu = @divTrunc(cgu * (1 << 16) + 0x8000, cy);
        cgv = @divTrunc(cgv * (1 << 16) + 0x8000, cy);
        var yb: i64 = -(384 << 16) - 512 * cy - oy;
        t.yb0 = yb;
        t.cy = @intCast(cy);
        for (0..2048) |i| {
            t.ytab[i] = clipU8(@intCast((yb + 0x8000) >> 16));
            yb += cy;
        }
        for (0..256) |i| {
            const v: i64 = @intCast(i);
            t.roff[i] = @intCast(((v * crv) >> 16) - (crv >> 9));
            t.boff[i] = @intCast(((v * cbu) >> 16) - (cbu >> 9));
            t.guoff[i] = @intCast(((v * cgu) >> 16) - (cgu >> 9));
            t.gvoff[i] = @intCast(((v * cgv) >> 16) - (cgv >> 9));
        }
    }
};

const YOFFS = 326 + 512;

inline fn clipU8(v: i32) u8 {
    return if (v < 0) 0 else if (v > 255) 255 else @intCast(v);
}
inline fn chrIdx(v: i32) usize {
    return clipU8(v);
}
inline fn ylook(t: *const Yuv2Rgb, idx: i32) u8 {
    const i: usize = @intCast(std.math.clamp(idx, 0, 2047));
    return t.ytab[i];
}

// ── Filter construction (port of initFilter) ────────────────────────────────

const Filter = struct {
    pos: []i32,
    coef: []i16,
    size: usize,
    n: usize,

    fn deinit(f: *Filter) void {
        alloc.free(f.pos);
        alloc.free(f.coef);
    }
};

fn avLog2(v: u32) i32 {
    if (v == 0) return 0;
    return 31 - @as(i32, @clz(v));
}
fn roundedDiv(a: i64, b: i64) i64 {
    return @divTrunc(if (a >= 0) a + (b >> 1) else a - (b >> 1), b);
}
fn iabs(a: i64) i64 {
    return if (a < 0) -a else a;
}

fn initFilter(xInc: i64, srcW: i32, dstW: i32, one: i64, algo: c_int, srcPos: i64, dstPos: i64) !Filter {
    const dw: usize = @intCast(dstW);
    const ratio: u32 = @intCast(@divTrunc(srcW, dstW));
    const fone: i64 = @as(i64, 1) << @intCast(54 - @min(avLog2(ratio), 8));
    const pos = try alloc.alloc(i32, dw + 3);
    var filterSize: i32 = 1;
    var filter: []i64 = undefined;

    if (iabs(xInc - 0x10000) < 10 and srcPos == dstPos) {
        filterSize = 1;
        filter = try alloc.alloc(i64, dw);
        for (0..dw) |i| {
            filter[i] = fone;
            pos[i] = @intCast(i);
        }
    } else if (algo == ALGO_NEAREST) {
        filterSize = 1;
        filter = try alloc.alloc(i64, dw);
        var xDstInSrc: i64 = ((dstPos * xInc) >> 8) - ((srcPos * 0x8000) >> 7);
        for (0..dw) |i| {
            const xx: i64 = (xDstInSrc - ((@as(i64, filterSize) - 1) << 15) + (1 << 15)) >> 16;
            pos[i] = @intCast(xx);
            filter[i] = fone;
            xDstInSrc += xInc;
        }
    } else {
        const sizeFactor: i32 = if (algo == ALGO_BICUBIC) 4 else 2;
        if (xInc <= 1 << 16) {
            filterSize = 1 + sizeFactor;
        } else {
            filterSize = 1 + @divTrunc(sizeFactor * srcW + dstW - 1, dstW);
        }
        filterSize = @min(filterSize, srcW - 2);
        filterSize = @max(filterSize, 1);
        const fs: usize = @intCast(filterSize);
        filter = try alloc.alloc(i64, dw * fs);
        var xDstInSrc: i64 = ((dstPos * xInc) >> 7) - ((srcPos * 0x10000) >> 7);
        for (0..dw) |i| {
            var xx: i64 = @divTrunc(xDstInSrc - (@as(i64, filterSize) - 2) * (1 << 16), 1 << 17);
            pos[i] = @intCast(xx);
            for (0..fs) |j| {
                var d: i64 = iabs(xx * (1 << 17) - xDstInSrc) << 13;
                if (xInc > 1 << 16) d = @divTrunc(d * dstW, srcW);
                var cf: i64 = 0;
                if (algo == ALGO_BICUBIC) {
                    const B: i64 = 0;
                    const C: i64 = @intFromFloat(0.6 * @as(f64, 1 << 24));
                    if (d >= 1 << 31) {
                        cf = 0;
                    } else {
                        const dd: i64 = (d * d) >> 30;
                        const ddd: i64 = (dd * d) >> 30;
                        if (d < 1 << 30) {
                            cf = (12 * (1 << 24) - 9 * B - 6 * C) * ddd +
                                (-18 * (1 << 24) + 12 * B + 6 * C) * dd +
                                (6 * (1 << 24) - 2 * B) * (1 << 30);
                        } else {
                            cf = (-B - 6 * C) * ddd +
                                (6 * B + 30 * C) * dd +
                                (-12 * B - 48 * C) * d +
                                (8 * B + 24 * C) * (1 << 30);
                        }
                    }
                    cf = @divTrunc(cf, @divTrunc(@as(i64, 1) << 54, fone));
                } else {
                    cf = (1 << 30) - d;
                    if (cf < 0) cf = 0;
                    cf *= fone >> 30;
                }
                filter[i * fs + j] = cf;
                xx += 1;
            }
            xDstInSrc += 2 * xInc;
        }
    }
    defer alloc.free(filter);

    const f2s: usize = @intCast(filterSize);
    const cutoffLimit: f64 = 0.002 * @as(f64, @floatFromInt(fone));
    // step 1: find the minimal size, shifting near-zero leading taps away
    var minFilterSize: usize = 0;
    var ii: isize = @as(isize, @intCast(dw)) - 1;
    while (ii >= 0) : (ii -= 1) {
        const i: usize = @intCast(ii);
        var min: usize = f2s;
        var cutOff: i64 = 0;
        var j: usize = 0;
        while (j < f2s) : (j += 1) {
            cutOff += iabs(filter[i * f2s]);
            if (@as(f64, @floatFromInt(cutOff)) > cutoffLimit) break;
            if (i < dw - 1 and pos[i] >= pos[i + 1]) break;
            var k: usize = 1;
            while (k < f2s) : (k += 1) filter[i * f2s + k - 1] = filter[i * f2s + k];
            filter[i * f2s + k - 1] = 0;
            pos[i] += 1;
        }
        cutOff = 0;
        var jj: usize = f2s - 1;
        while (jj > 0) : (jj -= 1) {
            cutOff += iabs(filter[i * f2s + jj]);
            if (@as(f64, @floatFromInt(cutOff)) > cutoffLimit) break;
            min -= 1;
        }
        if (min > minFilterSize) minFilterSize = min;
    }
    const fsz = minFilterSize;
    const f3 = try alloc.alloc(i64, dw * fsz);
    defer alloc.free(f3);
    for (0..dw) |i| {
        for (0..fsz) |j| {
            f3[i * fsz + j] = if (j >= f2s) 0 else filter[i * f2s + j];
        }
    }
    const sw: i32 = srcW;
    const fsi: i32 = @intCast(fsz);
    // fix borders
    for (0..dw) |i| {
        if (pos[i] < 0) {
            var j: usize = 1;
            while (j < fsz) : (j += 1) {
                const left: usize = @intCast(@max(@as(i32, @intCast(j)) + pos[i], 0));
                f3[i * fsz + left] += f3[i * fsz + j];
                f3[i * fsz + j] = 0;
            }
            pos[i] = 0;
        }
        if (pos[i] + fsi > sw) {
            const shift: i32 = pos[i] + @min(fsi - sw, 0);
            var acc: i64 = 0;
            var j: isize = @as(isize, @intCast(fsz)) - 1;
            while (j >= 0) : (j -= 1) {
                const ju: usize = @intCast(j);
                if (pos[i] + @as(i32, @intCast(j)) >= sw) {
                    acc += f3[i * fsz + ju];
                    f3[i * fsz + ju] = 0;
                }
            }
            j = @as(isize, @intCast(fsz)) - 1;
            while (j >= 0) : (j -= 1) {
                const ju: usize = @intCast(j);
                if (j < shift) {
                    f3[i * fsz + ju] = 0;
                } else {
                    f3[i * fsz + ju] = f3[i * fsz + ju - @as(usize, @intCast(shift))];
                }
            }
            pos[i] -= shift;
            f3[i * fsz + @as(usize, @intCast(sw - 1 - pos[i]))] += acc;
        }
    }
    // normalize
    const out = try alloc.alloc(i16, fsz * (dw + 3));
    @memset(out, 0);
    for (0..dw) |i| {
        var err: i64 = 0;
        var sum: i64 = 0;
        for (0..fsz) |j| sum += f3[i * fsz + j];
        sum = @divTrunc(sum + @divTrunc(one, 2), one);
        if (sum == 0) sum = 1;
        for (0..fsz) |j| {
            const v: i64 = f3[i * fsz + j] + err;
            const intV: i64 = roundedDiv(v, sum);
            out[i * fsz + j] = @truncate(intV);
            err = v - intV * sum;
        }
    }
    pos[dw] = pos[dw - 1];
    pos[dw + 1] = pos[dw - 1];
    pos[dw + 2] = pos[dw - 1];
    return .{ .pos = pos, .coef = out, .size = fsz, .n = dw };
}

// ── Context ─────────────────────────────────────────────────────────────────

const Mode = enum { yuv2rgb_unscaled, rgb2rgb, bgr24_to_yv12, plane_copy, yv12_to_nv, nv_to_yv12, generic };

const Ctx = struct {
    sw: usize,
    sh: usize,
    sf: c_int,
    dw: usize,
    dh: usize,
    df: c_int,
    algo: c_int,
    mode: Mode,
    tab: Yuv2Rgb,

    // generic pipeline
    hl: Filter = undefined,
    hc: Filter = undefined,
    vl: Filter = undefined,
    vc: Filter = undefined,
    chrSrcW: usize = 0,
    chrSrcH: usize = 0,
    chrDstW: usize = 0,
    chrDstH: usize = 0,
    chrSrcHSub: u5 = 0,
    chrSrcVSub: u5 = 0,
    chrDstHSub: u5 = 0,
    chrDstVSub: u5 = 0,
    fullChr: bool = false,
    needAlpha: bool = false,
    needChr: bool = false,
    lumBuf: []i16 = &.{},
    alpBuf: []i16 = &.{},
    chrU: []i16 = &.{},
    chrV: []i16 = &.{},
    lumNeed: []bool = &.{},
    chrNeed: []bool = &.{},
    tmpA: []u16 = &.{},
    tmpB: []u16 = &.{},
    tmpC: []u16 = &.{},
    lumStride: usize = 0,
    chrStride: usize = 0,
};

fn ceilShift(v: usize, s: u5) usize {
    return (v + ((@as(usize, 1) << s) - 1)) >> s;
}

fn chooseMode(c: *Ctx) Mode {
    if (c.sw != c.dw or c.sh != c.dh) return .generic;
    const s = c.sf;
    const d = c.df;
    var m: Mode = .generic;
    if (s == YUV420P and (d == NV12 or d == NV21)) m = .yv12_to_nv;
    if (d == YUV420P and (s == NV12 or s == NV21)) m = .nv_to_yv12;
    if ((s == YUV420P or s == YUV422P) and isRGB(d) and (c.dh & 1) == 0) m = .yuv2rgb_unscaled;
    if (s == BGR24 and d == YUV420P and (c.dw & 1) == 0) m = .bgr24_to_yv12;
    if (isRGB(s) and isRGB(d)) m = .rgb2rgb;
    if (s == d) {
        m = if (isRGB(s)) .rgb2rgb else .plane_copy;
    }
    // planar YUV <-> planar gray, or identical subsampling: plain copies
    const sPlanar = isPlanarYUV(s) and !isSemi(s);
    const dPlanar = isPlanarYUV(d) and !isSemi(d);
    if ((sPlanar and d == GRAY8) or (dPlanar and s == GRAY8)) m = .plane_copy;
    return m;
}

fn setupGeneric(c: *Ctx) !void {
    const sw: i32 = @intCast(c.sw);
    const sh: i32 = @intCast(c.sh);
    const dw: i32 = @intCast(c.dw);
    const dh: i32 = @intCast(c.dh);
    c.chrSrcHSub = hSub(c.sf);
    c.chrSrcVSub = vSub(c.sf);
    c.chrDstHSub = hSub(c.df);
    c.chrDstVSub = vSub(c.df);
    if (isRGB(c.df)) {
        c.fullChr = (c.dw & 1) != 0 or (c.chrSrcHSub == 0 and c.chrSrcVSub == 0);
        if (!c.fullChr) c.chrDstHSub = 1;
    }
    if (isRGB(c.sf) and (c.dw >> c.chrDstHSub) <= (c.sw >> 1)) c.chrSrcHSub = 1;
    c.chrSrcW = ceilShift(c.sw, c.chrSrcHSub);
    c.chrSrcH = ceilShift(c.sh, c.chrSrcVSub);
    c.chrDstW = ceilShift(c.dw, c.chrDstHSub);
    c.chrDstH = ceilShift(c.dh, c.chrDstVSub);
    c.needAlpha = hasAlphaFmt(c.sf) and hasAlphaFmt(c.df);
    c.needChr = c.df != GRAY8;

    const lumXInc: i64 = @divTrunc((@as(i64, sw) << 16) + (dw >> 1), dw);
    const lumYInc: i64 = @divTrunc((@as(i64, sh) << 16) + (dh >> 1), dh);
    const csw: i64 = @intCast(c.chrSrcW);
    const csh: i64 = @intCast(c.chrSrcH);
    const cdw: i64 = @intCast(c.chrDstW);
    const cdh: i64 = @intCast(c.chrDstH);
    const chrXInc: i64 = @divTrunc((csw << 16) + (cdw >> 1), cdw);
    const chrYInc: i64 = @divTrunc((csh << 16) + (cdh >> 1), cdh);

    c.hl = try initFilter(lumXInc, sw, dw, 1 << 14, c.algo, 128, 128);
    c.hc = try initFilter(chrXInc, @intCast(csw), @intCast(cdw), 1 << 14, c.algo, 128, 128);
    c.vl = try initFilter(lumYInc, sh, dh, 1 << 12, c.algo, 128, 128);
    c.vc = try initFilter(chrYInc, @intCast(csh), @intCast(cdh), 1 << 12, c.algo, 128, 128);

    // intermediate line storage: one hscaled line per source line (padded)
    c.lumStride = (c.dw + 16) & ~@as(usize, 15);
    c.chrStride = (c.chrDstW + 16) & ~@as(usize, 15);
    c.lumBuf = try alloc.alloc(i16, c.lumStride * c.sh);
    if (c.needAlpha) c.alpBuf = try alloc.alloc(i16, c.lumStride * c.sh);
    c.chrU = try alloc.alloc(i16, c.chrStride * c.chrSrcH);
    c.chrV = try alloc.alloc(i16, c.chrStride * c.chrSrcH);
    // grey sources have no chroma: swscale leaves its lines at 1<<14
    @memset(c.chrU, 1 << 14);
    @memset(c.chrV, 1 << 14);
    c.lumNeed = try alloc.alloc(bool, c.sh);
    c.chrNeed = try alloc.alloc(bool, c.chrSrcH);
    @memset(c.lumNeed, false);
    @memset(c.chrNeed, false);
    for (0..c.dh) |y| {
        const p: usize = @intCast(c.vl.pos[y]);
        for (0..c.vl.size) |j| {
            if (p + j < c.sh) c.lumNeed[p + j] = true;
        }
    }
    for (0..c.chrDstH) |y| {
        const p: usize = @intCast(c.vc.pos[y]);
        for (0..c.vc.size) |j| {
            if (p + j < c.chrSrcH) c.chrNeed[p + j] = true;
        }
    }
    const tw = c.sw * 2 + 64;
    c.tmpA = try alloc.alloc(u16, tw);
    c.tmpB = try alloc.alloc(u16, tw);
    c.tmpC = try alloc.alloc(u16, tw);
}

// ── Horizontal scaling ──────────────────────────────────────────────────────

fn hscale8(dst: []i16, src: [*]const u8, f: *const Filter) void {
    simd.hscale(u8, dst, src, f.pos, f.coef, f.size, f.n, 7);
}
fn hscale16(dst: []i16, src: [*]const u16, f: *const Filter) void {
    simd.hscale(u16, dst, src, f.pos, f.coef, f.size, f.n, 13);
}

// RGB input converters (input.c); every packed RGB layout reduces to the
// same arithmetic once R, G, B are picked out.
fn rgbToY(dst: []u16, src: [*]const u8, w: usize, fmt: c_int) void {
    simd.rgbToY(dst, src, w, bpp(fmt), rIdx(fmt), bIdx(fmt), RY, GY, BY);
}
fn rgbToUV(du: []u16, dv: []u16, src: [*]const u8, w: usize, fmt: c_int) void {
    const p = bpp(fmt);
    const ri = rIdx(fmt);
    const bi = bIdx(fmt);
    const rnd: i32 = (256 << (RGB2YUV_SHIFT - 1)) + (1 << (RGB2YUV_SHIFT - 7));
    for (0..w) |i| {
        const r: i32 = src[p * i + ri];
        const g: i32 = src[p * i + 1];
        const b: i32 = src[p * i + bi];
        du[i] = @truncate(@as(u32, @bitCast(RU * r + GU * g + BU * b + rnd)) >> (RGB2YUV_SHIFT - 6));
        dv[i] = @truncate(@as(u32, @bitCast(RV * r + GV * g + BV * b + rnd)) >> (RGB2YUV_SHIFT - 6));
    }
}
fn rgbToUVHalf(du: []u16, dv: []u16, src: [*]const u8, w: usize, fmt: c_int) void {
    simd.rgbToUVHalf(du, dv, src, w, bpp(fmt), rIdx(fmt), bIdx(fmt), RU, GU, BU, RV, GV, BV);
}

fn hscaleLine(c: *Ctx, y: usize, src: [*]const ?[*]const u8, ss: [*]const c_int) void {
    const sf = c.sf;
    const s0 = src[0].?;
    const st0: usize = @intCast(ss[0]);
    const row = s0 + y * st0;
    const dst = c.lumBuf[y * c.lumStride ..][0..c.dw];
    if (isRGB(sf)) {
        rgbToY(c.tmpA, row, c.sw, sf);
        hscale16(dst, c.tmpA.ptr, &c.hl);
        if (c.needAlpha) {
            for (0..c.sw) |i| {
                const a: u16 = row[4 * i + 3];
                c.tmpA[i] = (a << 6) | (a >> 2);
            }
            hscale16(c.alpBuf[y * c.lumStride ..][0..c.dw], c.tmpA.ptr, &c.hl);
        }
    } else {
        hscale8(dst, row, &c.hl);
    }
}

fn hscaleChrLine(c: *Ctx, y: usize, src: [*]const ?[*]const u8, ss: [*]const c_int) void {
    const sf = c.sf;
    if (sf == GRAY8) return;
    const du = c.chrU[y * c.chrStride ..][0..c.chrDstW];
    const dv = c.chrV[y * c.chrStride ..][0..c.chrDstW];
    if (isRGB(sf)) {
        // packed RGB: chroma rows are the luma rows (no vertical subsampling)
        const row = src[0].? + y * @as(usize, @intCast(ss[0]));
        if (c.chrSrcHSub == 1) {
            rgbToUVHalf(c.tmpB, c.tmpC, row, c.chrSrcW, sf);
        } else {
            rgbToUV(c.tmpB, c.tmpC, row, c.chrSrcW, sf);
        }
        hscale16(du, c.tmpB.ptr, &c.hc);
        hscale16(dv, c.tmpC.ptr, &c.hc);
    } else if (isSemi(sf)) {
        const row = src[1].? + y * @as(usize, @intCast(ss[1]));
        const t8u: [*]u8 = @ptrCast(c.tmpB.ptr);
        const t8v: [*]u8 = @ptrCast(c.tmpC.ptr);
        const swap = sf == NV21;
        for (0..c.chrSrcW) |i| {
            const a = row[2 * i];
            const b = row[2 * i + 1];
            t8u[i] = if (swap) b else a;
            t8v[i] = if (swap) a else b;
        }
        hscale8(du, t8u, &c.hc);
        hscale8(dv, t8v, &c.hc);
    } else {
        const ru = src[1].? + y * @as(usize, @intCast(ss[1]));
        const rv = src[2].? + y * @as(usize, @intCast(ss[2]));
        hscale8(du, ru, &c.hc);
        hscale8(dv, rv, &c.hc);
    }
}

// ── Vertical scaling / output ───────────────────────────────────────────────

fn lumLines(c: *Ctx, buf: []i16, y: usize, out: *[64][*]const i16) []const i16 {
    const p: usize = @intCast(c.vl.pos[y]);
    for (0..c.vl.size) |j| {
        const l = @min(p + j, c.sh - 1);
        out[j] = buf[l * c.lumStride ..].ptr;
    }
    return c.vl.coef[y * c.vl.size ..][0..c.vl.size];
}
fn chrLines(c: *Ctx, buf: []i16, y: usize, out: *[64][*]const i16) []const i16 {
    const p: usize = @intCast(c.vc.pos[y]);
    for (0..c.vc.size) |j| {
        const l = @min(p + j, c.chrSrcH - 1);
        out[j] = buf[l * c.chrStride ..].ptr;
    }
    return c.vc.coef[y * c.vc.size ..][0..c.vc.size];
}

fn processGeneric(c: *Ctx, src: [*]const ?[*]const u8, ss: [*]const c_int, dst: [*]const ?[*]u8, ds: [*]const c_int) void {
    for (0..c.sh) |y| {
        if (c.lumNeed[y]) hscaleLine(c, y, src, ss);
    }
    if (c.needChr) {
        for (0..c.chrSrcH) |y| {
            if (c.chrNeed[y]) hscaleChrLine(c, y, src, ss);
        }
    }
    var L: [64][*]const i16 = undefined;
    var A: [64][*]const i16 = undefined;
    var U: [64][*]const i16 = undefined;
    var V: [64][*]const i16 = undefined;
    const df = c.df;
    const d0 = dst[0].?;
    const st0: usize = @intCast(ds[0]);
    for (0..c.dh) |y| {
        const out = d0 + y * st0;
        if (!isRGB(df)) {
            const lf = lumLines(c, c.lumBuf, y, &L);
            simd.vplane(out, L[0..lf.len], lf, c.dw);
            if (!c.needChr) continue;
            if ((y & ((@as(usize, 1) << c.chrDstVSub) - 1)) != 0) continue;
            const cy = y >> c.chrDstVSub;
            const cf = chrLines(c, c.chrU, cy, &U);
            _ = chrLines(c, c.chrV, cy, &V);
            if (isSemi(df)) {
                const o = dst[1].? + cy * @as(usize, @intCast(ds[1]));
                simd.vnv(o, U[0..cf.len], V[0..cf.len], cf, c.chrDstW, df == NV21);
            } else {
                const ou = dst[1].? + cy * @as(usize, @intCast(ds[1]));
                const ov = dst[2].? + cy * @as(usize, @intCast(ds[2]));
                simd.vplane(ou, U[0..cf.len], cf, c.chrDstW);
                simd.vplane(ov, V[0..cf.len], cf, c.chrDstW);
            }
        } else {
            const lf = lumLines(c, c.lumBuf, y, &L);
            if (c.needAlpha) _ = lumLines(c, c.alpBuf, y, &A);
            const cf = chrLines(c, c.chrU, y, &U);
            _ = chrLines(c, c.chrV, y, &V);
            outputPacked(c, out, L[0..lf.len], lf, U[0..cf.len], V[0..cf.len], cf, if (c.needAlpha) A[0..lf.len] else null);
        }
    }
}

fn outputPacked(c: *Ctx, out: [*]u8, L: []const [*]const i16, lf: []const i16, U: []const [*]const i16, V: []const [*]const i16, cf: []const i16, A: ?[]const [*]const i16) void {
    const ls = lf.len;
    const cs = cf.len;
    var kind: enum { one, two, x } = .x;
    var uvalpha: i32 = 0;
    var yalpha: i32 = 0;
    const c0: i32 = cf[0];
    const c1: i32 = if (cs > 1) cf[1] else 0;
    if (ls == 1 and cs == 1) {
        kind = .one;
        uvalpha = 0;
    } else if (ls == 1 and cs == 2 and c0 + c1 == 4096 and c1 >= 0 and c1 <= 4096) {
        kind = .one;
        uvalpha = c1;
    } else if (ls == 2 and cs == 2 and @as(i32, lf[0]) + lf[1] == 4096 and lf[1] >= 0 and lf[1] <= 4096 and
        c0 + c1 == 4096 and c1 >= 0 and c1 <= 4096)
    {
        kind = .two;
        yalpha = lf[1];
        uvalpha = c1;
    }
    const p = bpp(c.df);
    const ri = rIdx(c.df);
    const bi = bIdx(c.df);
    const t = &c.tab;
    if (c.fullChr) {
        switch (kind) {
            .one => simd.full1(t, out, L[0], U, V, if (A) |a| a[0] else null, c.dw, uvalpha, p, ri, bi),
            .two => simd.full2(t, out, L, U, V, A, c.dw, yalpha, uvalpha, p, ri, bi),
            .x => simd.fullX(t, out, L, lf, U, V, cf, A, c.dw, p, ri, bi),
        }
        return;
    }
    // half-horizontal chroma via the yuv2rgb tables
    const pairs = (c.dw + 1) >> 1;
    for (0..pairs) |i| {
        var Y1: i32 = undefined;
        var Y2: i32 = undefined;
        var u: i32 = undefined;
        var v: i32 = undefined;
        switch (kind) {
            .one => {
                Y1 = (@as(i32, L[0][2 * i]) + 64) >> 7;
                Y2 = (@as(i32, L[0][2 * i + 1]) + 64) >> 7;
                if (uvalpha < 2048) {
                    u = (@as(i32, U[0][i]) + 64) >> 7;
                    v = (@as(i32, V[0][i]) + 64) >> 7;
                } else {
                    u = (@as(i32, U[0][i]) + U[1][i] + 128) >> 8;
                    v = (@as(i32, V[0][i]) + V[1][i] + 128) >> 8;
                }
            },
            .two => {
                const ya1 = 4096 - yalpha;
                const ua1 = 4096 - uvalpha;
                Y1 = (@as(i32, L[0][2 * i]) * ya1 + @as(i32, L[1][2 * i]) * yalpha) >> 19;
                Y2 = (@as(i32, L[0][2 * i + 1]) * ya1 + @as(i32, L[1][2 * i + 1]) * yalpha) >> 19;
                u = (@as(i32, U[0][i]) * ua1 + @as(i32, U[1][i]) * uvalpha) >> 19;
                v = (@as(i32, V[0][i]) * ua1 + @as(i32, V[1][i]) * uvalpha) >> 19;
            },
            .x => {
                Y1 = 1 << 18;
                Y2 = 1 << 18;
                u = 1 << 18;
                v = 1 << 18;
                for (0..ls) |j| {
                    Y1 +%= @as(i32, L[j][2 * i]) * lf[j];
                    Y2 +%= @as(i32, L[j][2 * i + 1]) * lf[j];
                }
                for (0..cs) |j| {
                    u +%= @as(i32, U[j][i]) * cf[j];
                    v +%= @as(i32, V[j][i]) * cf[j];
                }
                Y1 >>= 19;
                Y2 >>= 19;
                u >>= 19;
                v >>= 19;
            },
        }
        const ro = t.roff[chrIdx(v)];
        const go = t.guoff[chrIdx(u)] + t.gvoff[chrIdx(v)];
        const bo = t.boff[chrIdx(u)];
        const o = out + 2 * i * p;
        o[ri] = ylook(t, YOFFS + Y1 + ro);
        o[1] = ylook(t, YOFFS + Y1 + go);
        o[bi] = ylook(t, YOFFS + Y1 + bo);
        if (p == 4) o[3] = 255;
        if (2 * i + 1 < c.dw) {
            o[p + ri] = ylook(t, YOFFS + Y2 + ro);
            o[p + 1] = ylook(t, YOFFS + Y2 + go);
            o[p + bi] = ylook(t, YOFFS + Y2 + bo);
            if (p == 4) o[p + 3] = 255;
        }
    }
}

// ── Unscaled special converters ─────────────────────────────────────────────

fn processUnscaled(c: *Ctx, src: [*]const ?[*]const u8, ss: [*]const c_int, dst: [*]const ?[*]u8, ds: [*]const c_int) void {
    const w = c.sw;
    const h = c.sh;
    switch (c.mode) {
        .yuv2rgb_unscaled => {
            const is422 = c.sf == YUV422P;
            simd.yuv2rgbUnscaled(&c.tab, src, ss, dst[0].?, @intCast(ds[0]), w, h, is422, bpp(c.df), rIdx(c.df), bIdx(c.df));
        },
        .rgb2rgb => {
            const sp = bpp(c.sf);
            const dp = bpp(c.df);
            const sri = rIdx(c.sf);
            const dri = rIdx(c.df);
            for (0..h) |y| {
                const s = src[0].? + y * @as(usize, @intCast(ss[0]));
                const d = dst[0].? + y * @as(usize, @intCast(ds[0]));
                simd.rgbShuffle(d, s, w, sp, dp, sri, dri);
            }
        },
        .bgr24_to_yv12 => {
            simd.bgr24ToYv12(src[0].?, @intCast(ss[0]), dst, ds, w, h, RY, GY, BY, RU, GU, BU, RV, GV, BV);
        },
        .plane_copy => {
            copyPlane(dst[0].?, @intCast(ds[0]), src[0].?, @intCast(ss[0]), w, h);
            if (isPlanarYUV(c.df)) {
                const cw = ceilShift(w, hSub(c.df));
                const ch = ceilShift(h, vSub(c.df));
                if (c.sf == GRAY8) {
                    for (1..3) |pl| {
                        for (0..ch) |y| @memset((dst[pl].? + y * @as(usize, @intCast(ds[pl])))[0..cw], 128);
                    }
                } else {
                    for (1..3) |pl| copyPlane(dst[pl].?, @intCast(ds[pl]), src[pl].?, @intCast(ss[pl]), cw, ch);
                }
            }
        },
        .yv12_to_nv => {
            copyPlane(dst[0].?, @intCast(ds[0]), src[0].?, @intCast(ss[0]), w, h);
            const cw = w / 2;
            const swap = c.df == NV21;
            for (0..h / 2) |y| {
                const u = src[1].? + y * @as(usize, @intCast(ss[1]));
                const v = src[2].? + y * @as(usize, @intCast(ss[2]));
                const d = dst[1].? + y * @as(usize, @intCast(ds[1]));
                simd.interleave(d, if (swap) v else u, if (swap) u else v, cw);
            }
        },
        .nv_to_yv12 => {
            copyPlane(dst[0].?, @intCast(ds[0]), src[0].?, @intCast(ss[0]), w, h);
            const cw = w / 2;
            const swap = c.sf == NV21;
            for (0..h / 2) |y| {
                const s = src[1].? + y * @as(usize, @intCast(ss[1]));
                const u = dst[1].? + y * @as(usize, @intCast(ds[1]));
                const v = dst[2].? + y * @as(usize, @intCast(ds[2]));
                simd.deinterleave(if (swap) v else u, if (swap) u else v, s, cw);
            }
        },
        .generic => unreachable,
    }
}

fn copyPlane(d: [*]u8, dst_stride: usize, s: [*]const u8, src_stride: usize, w: usize, h: usize) void {
    for (0..h) |y| @memcpy((d + y * dst_stride)[0..w], (s + y * src_stride)[0..w]);
}

// ── Exported functions ──────────────────────────────────────────────────────

export fn swscale_create(src_w: c_int, src_h: c_int, src_fmt: c_int, dst_w: c_int, dst_h: c_int, dst_fmt: c_int, algo: c_int) ?*anyopaque {
    if (src_fmt < 0 or src_fmt > 9 or dst_fmt < 0 or dst_fmt > 9) return null;
    if (algo < 0 or algo > 2) return null;
    if (src_w < 4 or src_h < 4 or dst_w < 4 or dst_h < 4) return null;
    const c = alloc.create(Ctx) catch return null;
    c.* = .{
        .sw = @intCast(src_w),
        .sh = @intCast(src_h),
        .sf = src_fmt,
        .dw = @intCast(dst_w),
        .dh = @intCast(dst_h),
        .df = dst_fmt,
        .algo = algo,
        .mode = .generic,
        .tab = undefined,
    };
    c.tab.init();
    c.mode = chooseMode(c);
    if (c.mode == .generic) {
        setupGeneric(c) catch {
            alloc.destroy(c);
            return null;
        };
    }
    return @ptrCast(c);
}

export fn swscale_process(handle: ?*anyopaque, src_data: [*]const ?[*]const u8, src_stride: [*]const c_int, dst_data: [*]const ?[*]u8, dst_stride: [*]const c_int) c_int {
    const c: *Ctx = @ptrCast(@alignCast(handle orelse return -1));
    if (c.mode == .generic) {
        processGeneric(c, src_data, src_stride, dst_data, dst_stride);
    } else {
        processUnscaled(c, src_data, src_stride, dst_data, dst_stride);
    }
    return 0;
}

export fn swscale_destroy(handle: ?*anyopaque) void {
    const c: *Ctx = @ptrCast(@alignCast(handle orelse return));
    if (c.mode == .generic) {
        c.hl.deinit();
        c.hc.deinit();
        c.vl.deinit();
        c.vc.deinit();
        alloc.free(c.lumBuf);
        if (c.needAlpha) alloc.free(c.alpBuf);
        alloc.free(c.chrU);
        alloc.free(c.chrV);
        alloc.free(c.lumNeed);
        alloc.free(c.chrNeed);
        alloc.free(c.tmpA);
        alloc.free(c.tmpB);
        alloc.free(c.tmpC);
    }
    alloc.destroy(c);
}

