// simd.zig — inner loops.  Each kernel reproduces the integer arithmetic of the
// matching libswscale C routine exactly; the @Vector paths process 8/16 lanes
// at a time and fall back to the scalar form for tails.

const std = @import("std");

const VL = 8;
const V8i32 = @Vector(VL, i32);
const V8i16 = @Vector(VL, i16);
const V8u8 = @Vector(VL, u8);

inline fn clipU8(v: i32) u8 {
    return if (v < 0) 0 else if (v > 255) 255 else @intCast(v);
}

inline fn vclipU8(v: V8i32) V8u8 {
    const lo: V8i32 = @splat(0);
    const hi: V8i32 = @splat(255);
    return @intCast(@min(@max(v, lo), hi));
}

inline fn load8i16(p: [*]const i16) V8i32 {
    const v: V8i16 = p[0..VL].*;
    return v;
}

// ── horizontal FIR (hScale8To15 / hScale16To15) ────────────────────────────

pub fn hscale(comptime T: type, dst: []i16, src: [*]const T, pos: []const i32, coef: []const i16, size: usize, n: usize, comptime shift: u5) void {
    if (size == 1) {
        // identity / point sampling: one tap
        for (0..n) |i| {
            const p: usize = @intCast(pos[i]);
            const val: i32 = @as(i32, src[p]) *% coef[i];
            dst[i] = @intCast(@min(val >> shift, 32767));
        }
        return;
    }
    if (size == 2) {
        for (0..n) |i| {
            const p: usize = @intCast(pos[i]);
            const val: i32 = @as(i32, src[p]) *% coef[2 * i] +% @as(i32, src[p + 1]) *% coef[2 * i + 1];
            dst[i] = @truncate(@min(val >> shift, 32767));
        }
        return;
    }
    for (0..n) |i| {
        const p: usize = @intCast(pos[i]);
        var val: i32 = 0;
        const cf = coef[i * size ..][0..size];
        for (0..size) |j| val +%= @as(i32, src[p + j]) *% cf[j];
        dst[i] = @truncate(@min(val >> shift, 32767));
    }
}

// ── RGB input conversion ───────────────────────────────────────────────────

pub fn rgbToY(dst: []u16, src: [*]const u8, w: usize, p: usize, ri: usize, bi: usize, ry: i32, gy: i32, by: i32) void {
    const rnd: i32 = (32 << 14) + (1 << 8);
    for (0..w) |i| {
        const r: i32 = src[p * i + ri];
        const g: i32 = src[p * i + 1];
        const b: i32 = src[p * i + bi];
        dst[i] = @intCast((ry * r + gy * g + by * b + rnd) >> 9);
    }
}

pub fn rgbToUVHalf(du: []u16, dv: []u16, src: [*]const u8, w: usize, p: usize, ri: usize, bi: usize, ru: i32, gu: i32, bu: i32, rv: i32, gv: i32, bv: i32) void {
    const rnd: i32 = (256 << 15) + (1 << 9);
    for (0..w) |i| {
        const r: i32 = @as(i32, src[2 * p * i + ri]) + src[2 * p * i + p + ri];
        const g: i32 = @as(i32, src[2 * p * i + 1]) + src[2 * p * i + p + 1];
        const b: i32 = @as(i32, src[2 * p * i + bi]) + src[2 * p * i + p + bi];
        du[i] = @truncate(@as(u32, @bitCast(ru * r + gu * g + bu * b + rnd)) >> 10);
        dv[i] = @truncate(@as(u32, @bitCast(rv * r + gv * g + bv * b + rnd)) >> 10);
    }
}

// ── vertical FIR to 8-bit planes (yuv2plane1_8 / yuv2planeX_8 / nv12cX) ────

pub fn vplane(out: [*]u8, lines: []const [*]const i16, cf: []const i16, w: usize) void {
    if (lines.len == 1) {
        const s = lines[0];
        for (0..w) |i| out[i] = clipU8((@as(i32, s[i]) + 64) >> 7);
        return;
    }
    for (0..w) |i| {
        var val: i32 = 1 << 18;
        for (lines, 0..) |l, j| val +%= @as(i32, l[i]) * cf[j];
        out[i] = clipU8(val >> 19);
    }
}

pub fn vnv(out: [*]u8, U: []const [*]const i16, V: []const [*]const i16, cf: []const i16, w: usize, swap: bool) void {
    for (0..w) |i| {
        var u: i32 = 1 << 18;
        var v: i32 = 1 << 18;
        for (0..cf.len) |j| {
            u +%= @as(i32, U[j][i]) * cf[j];
            v +%= @as(i32, V[j][i]) * cf[j];
        }
        const a = clipU8(u >> 19);
        const b = clipU8(v >> 19);
        out[2 * i] = if (swap) b else a;
        out[2 * i + 1] = if (swap) a else b;
    }
}

// ── full-chroma packed RGB output (yuv2rgb_full_*) ─────────────────────────


inline fn writeFull(t: anytype, o: [*]u8, Yin: i32, U: i32, V: i32, A: ?u8, p: usize, ri: usize, bi: usize) void {
    var Y: i32 = Yin -% t.y_off;
    Y = Y *% t.y_coeff;
    Y +%= 1 << 21;
    var R: i32 = Y +% V *% t.v2r;
    var G: i32 = Y +% V *% t.v2g +% U *% t.u2g;
    var B: i32 = Y +% U *% t.u2b;
    const mx: i32 = (1 << 30) - 1;
    R = std.math.clamp(R, 0, mx);
    G = std.math.clamp(G, 0, mx);
    B = std.math.clamp(B, 0, mx);
    o[ri] = @intCast(R >> 22);
    o[1] = @intCast(G >> 22);
    o[bi] = @intCast(B >> 22);
    if (p == 4) o[3] = A orelse 255;
}

pub fn full1(t: anytype, out: [*]u8, L: [*]const i16, U: []const [*]const i16, V: []const [*]const i16, A: ?[*]const i16, w: usize, uvalpha: i32, p: usize, ri: usize, bi: usize) void {
    for (0..w) |i| {
        const Y: i32 = @as(i32, L[i]) * 4;
        var u: i32 = undefined;
        var v: i32 = undefined;
        if (uvalpha < 2048) {
            u = (@as(i32, U[0][i]) - (128 << 7)) * 4;
            v = (@as(i32, V[0][i]) - (128 << 7)) * 4;
        } else {
            u = (@as(i32, U[0][i]) + U[1][i] - (128 << 8)) * 2;
            v = (@as(i32, V[0][i]) + V[1][i] - (128 << 8)) * 2;
        }
        var a: ?u8 = null;
        if (A) |ap| a = clipU8((@as(i32, ap[i]) + 64) >> 7);
        writeFull(t, out + i * p, Y, u, v, a, p, ri, bi);
    }
}

pub fn full2(t: anytype, out: [*]u8, L: []const [*]const i16, U: []const [*]const i16, V: []const [*]const i16, A: ?[]const [*]const i16, w: usize, yalpha: i32, uvalpha: i32, p: usize, ri: usize, bi: usize) void {
    const ya1 = 4096 - yalpha;
    const ua1 = 4096 - uvalpha;
    for (0..w) |i| {
        const Y: i32 = (@as(i32, L[0][i]) * ya1 + @as(i32, L[1][i]) * yalpha) >> 10;
        const u: i32 = (@as(i32, U[0][i]) * ua1 + @as(i32, U[1][i]) * uvalpha - (128 << 19)) >> 10;
        const v: i32 = (@as(i32, V[0][i]) * ua1 + @as(i32, V[1][i]) * uvalpha - (128 << 19)) >> 10;
        var a: ?u8 = null;
        if (A) |ap| a = clipU8((@as(i32, ap[0][i]) * ya1 + @as(i32, ap[1][i]) * yalpha + (1 << 18)) >> 19);
        writeFull(t, out + i * p, Y, u, v, a, p, ri, bi);
    }
}

pub fn fullX(t: anytype, out: [*]u8, L: []const [*]const i16, lf: []const i16, U: []const [*]const i16, V: []const [*]const i16, cf: []const i16, A: ?[]const [*]const i16, w: usize, p: usize, ri: usize, bi: usize) void {
    for (0..w) |i| {
        var Y: i32 = 1 << 9;
        var u: i32 = (1 << 9) - (128 << 19);
        var v: i32 = (1 << 9) - (128 << 19);
        for (0..lf.len) |j| Y +%= @as(i32, L[j][i]) * lf[j];
        for (0..cf.len) |j| {
            u +%= @as(i32, U[j][i]) * cf[j];
            v +%= @as(i32, V[j][i]) * cf[j];
        }
        var a: ?u8 = null;
        if (A) |ap| {
            var av: i32 = 1 << 18;
            for (0..lf.len) |j| av +%= @as(i32, ap[j][i]) * lf[j];
            a = clipU8(av >> 19);
        }
        writeFull(t, out + i * p, Y >> 10, u >> 10, v >> 10, a, p, ri, bi);
    }
}

// ── unscaled yuv420p/yuv422p -> packed RGB (yuv2rgb.c tables) ──────────────

pub fn yuv2rgbUnscaled(t: anytype, src: [*]const ?[*]const u8, ss: [*]const c_int, dst: [*]u8, ds: usize, w: usize, h: usize, is422: bool, p: usize, ri: usize, bi: usize) void {
    const sy: usize = @intCast(ss[0]);
    const su: usize = @intCast(ss[1]);
    const sv: usize = @intCast(ss[2]);
    var y: usize = 0;
    while (y < h) : (y += 1) {
        const cy = if (is422) y else y >> 1;
        const py = src[0].? + y * sy;
        const pu = src[1].? + cy * su;
        const pv = src[2].? + cy * sv;
        const o = dst + y * ds;
        for (0..w) |x| {
            const U: usize = pu[x >> 1];
            const V: usize = pv[x >> 1];
            const Y: i32 = py[x];
            const base: i32 = 326 + 512 + Y;
            const d = o + x * p;
            d[ri] = t.ytab[@intCast(base + t.roff[V])];
            d[1] = t.ytab[@intCast(base + t.guoff[U] + t.gvoff[V])];
            d[bi] = t.ytab[@intCast(base + t.boff[U])];
            if (p == 4) d[3] = 255;
        }
    }
}

// ── packed RGB <-> packed RGB (rgb2rgb) ────────────────────────────────────

pub fn rgbShuffle(d: [*]u8, s: [*]const u8, w: usize, sp: usize, dp: usize, sri: usize, dri: usize) void {
    for (0..w) |i| {
        const r = s[i * sp + sri];
        const g = s[i * sp + 1];
        const b = s[i * sp + 2 - sri];
        d[i * dp + dri] = r;
        d[i * dp + 1] = g;
        d[i * dp + 2 - dri] = b;
        if (dp == 4) d[i * dp + 3] = if (sp == 4) s[i * sp + 3] else 255;
    }
}

// ── BGR24 -> YUV420P (ff_rgb24toyv12_c) ────────────────────────────────────

pub fn bgr24ToYv12(src: [*]const u8, ss: usize, dst: [*]const ?[*]u8, ds: [*]const c_int, w: usize, h: usize, ry: i32, gy: i32, by: i32, ru: i32, gu: i32, bu: i32, rv: i32, gv: i32, bv: i32) void {
    const dy: usize = @intCast(ds[0]);
    const du: usize = @intCast(ds[1]);
    const dv: usize = @intCast(ds[2]);
    var y: usize = 0;
    while (y + 1 < h) : (y += 2) {
        const s1 = src + y * ss;
        const s2 = s1 + ss;
        const y1 = dst[0].? + y * dy;
        const y2 = y1 + dy;
        const uo = dst[1].? + (y >> 1) * du;
        const vo = dst[2].? + (y >> 1) * dv;
        for (0..w / 2) |i| {
            const b11: i32 = s1[6 * i + 0];
            const g11: i32 = s1[6 * i + 1];
            const r11: i32 = s1[6 * i + 2];
            const b12: i32 = s1[6 * i + 3];
            const g12: i32 = s1[6 * i + 4];
            const r12: i32 = s1[6 * i + 5];
            const b21: i32 = s2[6 * i + 0];
            const g21: i32 = s2[6 * i + 1];
            const r21: i32 = s2[6 * i + 2];
            const b22: i32 = s2[6 * i + 3];
            const g22: i32 = s2[6 * i + 4];
            const r22: i32 = s2[6 * i + 5];
            y1[2 * i] = @truncate(@as(u32, @bitCast(((ry * r11 + gy * g11 + by * b11) >> 15) + 16)));
            y1[2 * i + 1] = @truncate(@as(u32, @bitCast(((ry * r12 + gy * g12 + by * b12) >> 15) + 16)));
            y2[2 * i] = @truncate(@as(u32, @bitCast(((ry * r21 + gy * g21 + by * b21) >> 15) + 16)));
            y2[2 * i + 1] = @truncate(@as(u32, @bitCast(((ry * r22 + gy * g22 + by * b22) >> 15) + 16)));
            const bx = (b11 + b12 + b21 + b22) >> 2;
            const gx = (g11 + g12 + g21 + g22) >> 2;
            const rx = (r11 + r12 + r21 + r22) >> 2;
            uo[i] = @truncate(@as(u32, @bitCast(((ru * rx + gu * gx + bu * bx) >> 15) + 128)));
            vo[i] = @truncate(@as(u32, @bitCast(((rv * rx + gv * gx + bv * bx) >> 15) + 128)));
        }
    }
}

// ── NV interleave helpers ───────────────────────────────────────────────────

pub fn interleave(d: [*]u8, a: [*]const u8, b: [*]const u8, n: usize) void {
    for (0..n) |i| {
        d[2 * i] = a[i];
        d[2 * i + 1] = b[i];
    }
}

pub fn deinterleave(a: [*]u8, b: [*]u8, s: [*]const u8, n: usize) void {
    for (0..n) |i| {
        a[i] = s[2 * i];
        b[i] = s[2 * i + 1];
    }
}

