    const bi = 2 - ri;
    // build per-channel source table: lanes 0..7 = c0, 8..15 = c1 where (c0,c1,c2,c3) are bytes 0..3
    const ch0 = if (ri == 0) r else b;
    const ch2 = if (bi == 2) b else r;
    const lo: V16u8 = @shuffle(u8, ch0, g, blk2());
    const hi: V16u8 = @shuffle(u8, ch2, a, blk2());
    const m = comptime packMask(p);
    const res: @Vector(8 * p, u8) = @shuffle(u8, lo, hi, m);
    o[0 .. 8 * p].* = @as([8 * p]u8, res);
}

fn blk2() [16]i32 {
    var m: [16]i32 = undefined;
    for (0..8) |k| {
        m[k] = @intCast(k);
        m[8 + k] = ~@as(i32, @intCast(k));
    }
    return m;
}

fn packMask(comptime p: usize) [8 * p]i32 {
    var m: [8 * p]i32 = undefined;
    for (0..8) |k| {
        for (0..p) |c| {
            // channel c lives at: c=0 -> lo[k], c=1 -> lo[8+k], c=2 -> hi[k], c=3 -> hi[8+k]
            m[k * p + c] = switch (c) {
                0 => @intCast(k),
                1 => @intCast(8 + k),
                2 => ~@as(i32, @intCast(k)),
                else => ~@as(i32, @intCast(8 + k)),
            };
        }
    }
    return m;
}""","""inline fn store8(comptime p: usize, comptime ri: usize, o: [*]u8, r: V8u8, g: V8u8, b: V8u8, a: V8u8) void {
    storeN(8, p, ri, o, r, g, b, a);
}

inline fn storeN(comptime n: usize, comptime p: usize, comptime ri: usize, o: [*]u8, r: @Vector(n, u8), g: @Vector(n, u8), b: @Vector(n, u8), a: @Vector(n, u8)) void {
    const bi = 2 - ri;
    // lanes 0..n-1 = byte 0 channel, n..2n-1 = byte 1 (green); likewise bytes 2/3
    const ch0 = if (ri == 0) r else b;
    const ch2 = if (bi == 2) b else r;
    const lo: @Vector(2 * n, u8) = @shuffle(u8, ch0, g, comptime blk2(n));
