import sys, os, subprocess
sys.path.insert(0, "/app")
import workloads as W
lib = "/app/swscale-impl/zig-out/lib/libswscale_candidate.so"
cases = []
import itertools
sizes = [(642, 362, 642, 362), (322, 242, 160, 120), (100, 50, 333, 211), (1000, 700, 999, 701), (64, 48, 64, 48), (130, 98, 66, 50)]
for (sw, sh, dw, dh) in sizes:
    for (s, d) in W._PAIRS[::3] + [(W.NV12, W.NV12), (W.RGB24, W.RGB24), (W.YUV420P, W.YUV420P), (W.GRAY8, W.GRAY8)]:
        for algo in (0, 1, 2):
            odd = lambda f, v: (f in W.SUBSAMPLED) and (v & 1)
            if odd(s, sw) or odd(s, sh) or odd(d, dw) or odd(d, dh):
                continue
            cases.append(W._wl("x", s, d, sw, sh, dw, dh, algo))
bad = 0
for i, wl in enumerate(cases):
    if i % 2: continue
    outs = []
    for L in ("/app/libswscale_public_baseline.so", lib):
        o = f"/tmp/odd_{os.getpid()}.raw"
        p = subprocess.run(W.driver_argv("/app/driver", L, wl, 1, o), capture_output=True)
        outs.append(open(o, "rb").read() if p.returncode == 0 else None)
    if outs[0] is None:
        continue
    if outs[1] is None:
        print("FAIL(run)", wl["label"]); bad += 1; continue
    r = W.grade(outs[0], outs[1], wl["dst_fmt"], wl["dst_w"], wl["dst_h"], wl["scaling"])
    if r["status"] != "pass":
        bad += 1; print("DIFF", wl["label"], r.get("plane_psnr"))
print("checked", len(cases)//2 + len(cases)%2, "bad", bad)
EOF
